-- ----------------------------
-- Table structure for config_i18n
-- ----------------------------
DROP TABLE IF EXISTS `config_i18n`;
CREATE TABLE `config_i18n`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `primary_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '语言关键词',
  `language` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '语言',
  `language_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '语言值',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `show_type` int(11) NULL DEFAULT NULL COMMENT '使用类型 1服务端 2用户端',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_primary_key`(`primary_key`, `language`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4807 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '国际化配置表' ROW_FORMAT = DYNAMIC;

