-- ----------------------------
-- Table structure for goods
-- ----------------------------
DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods`  (
  `goods_id` int(11) NOT NULL AUTO_INCREMENT,
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品名称',
  `goods_synopsis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品简介',
  `goods_describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品描述',
  `classify_id` int(11) NULL DEFAULT NULL COMMENT '商品分类id（商品左侧菜单）',
  `goods_cover` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '商品封面图',
  `goods_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '商品图片',
  `goods_label` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品标签',
  `create_time` datetime NULL DEFAULT NULL COMMENT '上架时间',
  `sales_volume` int(11) NULL DEFAULT NULL COMMENT '销量',
  `status` int(11) NULL DEFAULT NULL COMMENT '是否上架 0上架  1下架',
  `pack_money` decimal(10, 2) NULL DEFAULT NULL COMMENT '商品打包费',
  `goods_money` decimal(10, 2) NULL DEFAULT NULL COMMENT '商品价格',
  `original_money` decimal(10, 2) NULL DEFAULT NULL COMMENT '原价',
  `shop_id` int(11) NULL DEFAULT 0 COMMENT '店铺id',
  PRIMARY KEY (`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 233 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '商品表' ROW_FORMAT = DYNAMIC;

